import { Check } from '@gntik-ai/icons';
import { Stack, Text } from '@gntik-ai/ui';

export interface BrandPanelCopy {
  eyebrow: string;
  headline: string;
  features: string[];
}

/** Brand panel body for AuthLayout `split`: eyebrow, headline and a short feature list (text only). */
export function BrandPanel({ eyebrow, headline, features }: BrandPanelCopy) {
  return (
    <Stack gap={8}>
      <Stack gap={4}>
        <Text variant="caption" tone="primary" className="font-mono tracking-[0.18em] uppercase">
          {eyebrow}
        </Text>
        <Text variant="display" className="text-[32px] text-balance">
          {headline}
        </Text>
      </Stack>
      <Stack as="ul" gap={3}>
        {features.map((feature) => (
          <Stack as="li" key={feature} direction="row" align="center" gap={3}>
            <Check size={16} aria-hidden className="shrink-0 text-primary-text" />
            <Text variant="supporting" tone="muted">
              {feature}
            </Text>
          </Stack>
        ))}
      </Stack>
    </Stack>
  );
}

import { SignInForm, SsoButtons, type SignInValues, type SsoProvider } from '@gntik-ai/blocks';
import { AuthLayout } from '@gntik-ai/ui';
import { useState, type ReactNode } from 'react';
import { BrandPanel, type BrandPanelCopy } from './BrandPanel';
import { signInBrand, signInSsoProviders } from './data';

export interface SignInPageProps {
  /** Heading above the form (default "Sign in to your workspace"). */
  title: ReactNode;
  /** Line under the heading (default "Use your work email to continue."). */
  description: ReactNode;
  /** Small label above the heading. */
  eyebrow: ReactNode;
  /** Signs in. A returned promise shows the loading state; a rejection's message shows in the alert. */
  onSubmit: (values: SignInValues) => void | Promise<void>;
  /** Starts single sign-on with a provider id; the button spins until the page navigates away. */
  onSso: (providerId: string) => void;
  ssoProviders: SsoProvider[];
  error: string | null;
  forgotPasswordHref: string;
  onForgotPassword: () => void;
  signUpHref: string;
  onSignUp: () => void;
  /** Brand panel copy (split layout, large screens). */
  brand: BrandPanelCopy;
  brandFooter: ReactNode;
  logo: ReactNode;
}

/** Split sign-in: AuthLayout brand panel + SignInForm with SsoButtons. */
export default function SignInPage({
  title,
  description,
  eyebrow,
  onSubmit,
  onSso,
  ssoProviders = signInSsoProviders,
  error,
  forgotPasswordHref,
  onForgotPassword,
  signUpHref,
  onSignUp,
  brand = signInBrand,
  brandFooter = signInBrand.footer,
  logo,
}: Partial<SignInPageProps>) {
  const [ssoLoading, setSsoLoading] = useState<string | null>(null);
  return (
    <AuthLayout fullScreen variant="split" logo={logo} brand={<BrandPanel {...brand} />} brandFooter={brandFooter}>
      <SignInForm
        title={title}
        description={description}
        eyebrow={eyebrow}
        onSubmit={onSubmit}
        error={error}
        forgotPasswordHref={forgotPasswordHref}
        onForgotPassword={onForgotPassword}
        signUpHref={signUpHref}
        onSignUp={onSignUp}
        sso={
          <SsoButtons
            providers={ssoProviders}
            loadingId={ssoLoading}
            onSelect={(id) => {
              setSsoLoading(id);
              onSso?.(id);
            }}
          />
        }
      />
    </AuthLayout>
  );
}

import { ssoProviders } from '@gntik-ai/blocks';

export { ssoProviders as signInSsoProviders };

/** Brand panel copy for the split layout. */
export const signInBrand = {
  eyebrow: 'Control plane',
  headline: 'Ship with confidence, not guesswork.',
  features: ['Every deployment reviewed and audited', 'Roles and access per project', 'Usage and spend in one place'],
  footer: 'MFA · recovery codes · audited access',
};
